.portal-autopost-boundary { display: grid; gap: 14px; }
.portal-autopost-boundary-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 9px; }
.portal-autopost-boundary-grid > div { display: grid; gap: 6px; min-width: 0; padding: 11px; border: 1px solid var(--portal-border); border-radius: 12px; background: var(--portal-surface-soft); }
.portal-autopost-boundary-grid strong { color: var(--portal-text); font-size: 11px; }
.portal-autopost-boundary-grid span { color: var(--portal-muted); font-size: 10px; line-height: 1.45; }
