  .portal-autopost-intro, .portal-autopost-layout { grid-template-columns: 1fr; }
  .portal-autopost-steps ol { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .portal-autopost-boundary-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 620px) {
  .portal-autopost-intro { padding: 20px; border-radius: 18px; }
  .portal-autopost-intro dl, .portal-autopost-steps ol, .portal-autopost-boundary-grid { grid-template-columns: 1fr; }
  .portal-autopost-source { grid-template-columns: 28px minmax(0, 1fr); }
  .portal-autopost-status { grid-column: 2; justify-self: start; }
}

/* Compact only the manual image editor's mobile workspace navigation. */
